pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MStableYieldSource} from "../src/MStableYieldSource.sol";
import {ISavingsContractV2} from "../src/MStableYieldSource.sol";

contract InvMutTest is Test {
    MStableYieldSource c;
    function setUp() public { c = new MStableYieldSource(ISavingsContractV2(address(new __InvMutHandleStub()))); }

    function testFuzz_property(uint96 amount, address actor, address to) public {
        uint256 amt = bound(uint256(amount), 1, 1e24);
        uint256 before = c.imBalances(to);
        vm.prank(actor);
        c.supplyTokenTo(amt, to);
        // General rule: after a successful supply, the recipient's credit balance
        // grows by exactly the credits issued for the deposited amount.
        assertTrue(c.imBalances(to) == before + amt, "recipient must be credited");
    }
}

